-- 0438_find_capabilities — make `find` discoverable through the capability graph.
--
-- Two seeds feed rvbbit.capability_crawl() (0147/0215): rvbbit.capability_seed
-- (cap_syntax / cap_operator docs for SQL-facing surfaces) and
-- rvbbit.capability_mcp_tools (one row per Warehouse MCP tool). Neither knew
-- about rvbbit.find / the `find` MCP tool (0437), and the MCP corpus had been
-- generated when most tools still registered through tool_* lambdas — the
-- generator could not see `_mcp_*` wrappers, so the table held 86 of 196
-- tools. scripts/gen_capability_mcp_tools.py now reads the wrapper docstrings
-- (the exact text agents see); the block below is its output and the table is
-- trimmed to it. The live search_tools/get_tool_help index is unaffected (it
-- reads the FastMCP registry directly); this is the semantic capability_search
-- side that Calliope, Hermes agents and DataRabbit use for discovery.

-- generated by scripts/gen_capability_mcp_tools.py — do not hand-edit rows
CREATE TABLE IF NOT EXISTS rvbbit.capability_mcp_tools (
    name    text PRIMARY KEY,
    summary text NOT NULL DEFAULT ''
);
ON CONFLICT (name) DO UPDATE SET summary = EXCLUDED.summary;

-- Rows for tools that are no longer registered on the Warehouse connector.
DELETE FROM rvbbit.capability_mcp_tools WHERE name <> ALL (ARRAY['acceleration_steward_snapshot', 'accept_proposal', 'administer_calliope_action', 'administer_local_sql', 'agent_overlay_list', 'agent_overlay_propose', 'agent_overlay_set_state', 'alert_events', 'alert_state', 'alert_sweep_runs', 'apply_hermes_config', 'approve_calliope_playbook', 'archive_calliope_page', 'archive_calliope_playbook', 'artifact_access_get', 'artifact_access_update', 'artifact_archive', 'artifact_restore', 'ask_brain', 'ask_calliope', 'ask_system_learning', 'await_calliope_specialists', 'begin_calliope_work_order_run', 'begin_calliope_workflow_run', 'bind_calliope_term', 'brain_browse', 'brain_context', 'brain_crawl_folder', 'brain_entity', 'brain_exclude', 'brain_facets', 'brain_get_doc', 'brain_grant', 'brain_ingest', 'brain_related', 'brain_set_doc_roles', 'breaching_alerts', 'breaching_kpis', 'business_context_changes', 'business_context_for_question', 'business_context_status', 'business_metric_change', 'calliope_decision_request', 'calliope_observation_context', 'calliope_session_access_get', 'calliope_session_access_update', 'calliope_sheet_query', 'calliope_sheet_snapshot', 'calliope_work_item', 'capability_search', 'capture_live_app', 'compare', 'connect_mirror_source', 'continue_calliope_specialist', 'create_calliope_page', 'create_calliope_sketch', 'create_cube', 'create_live_app', 'create_metric', 'create_mirror_job', 'cube_pivot', 'curate_calliope_memory', 'dashboard_crawl', 'dashboard_dependents', 'dashboard_template', 'debug_live_app', 'decide_workload_layout', 'delegate_all_calliope_specialists', 'delegate_calliope_specialist', 'describe_table', 'discover_mirror_source', 'draft_calliope_instrument', 'draft_calliope_playbook', 'draft_calliope_work_order', 'draft_calliope_workflow', 'edit_cube', 'edit_metric', 'enrich_live_app', 'export_to_google_sheets', 'extract_image', 'find', 'finish_calliope_work_order_run', 'finish_calliope_workflow_run', 'finish_page_refresh', 'generate_image', 'get_alert', 'get_business_value_system', 'get_calliope_personal_context', 'get_calliope_work_order_personal_context', 'get_dashboard', 'get_live_app', 'get_metric', 'get_proposal', 'get_tool_help', 'hermes_config_current', 'hermes_config_status', 'kit_rehearsal', 'list_alerts', 'list_artifact_areas', 'list_calliope_pages', 'list_calliope_specialist_threads', 'list_calliope_specialists', 'list_cubes', 'list_dashboards', 'list_live_apps', 'list_metrics', 'list_proposals', 'list_specialist_findings', 'live_app_logs', 'live_app_status', 'live_app_template', 'look_at_desktop', 'manage_workspace_job', 'materialize_metric', 'metric', 'metric_dimensions', 'metric_history', 'metric_lineage', 'mirror_status', 'mute_alert', 'pivot', 'preview_alert_condition', 'preview_metric_observation', 'profile_schema', 'propose_calliope_computer_action', 'propose_cube', 'propose_metric', 'publish_answer', 'publish_chart', 'publish_dashboard', 'publish_map', 'read_calliope_page', 'read_calliope_playbook', 'read_calliope_sketch', 'read_chart', 'read_map', 'read_page_refresh', 'record_acceleration_observation', 'record_specialist_finding', 'refine_proposal', 'refresh_business_context', 'refresh_calliope_page', 'render_pdf', 'request_calliope_input', 'resolve_specialist_finding', 'restart_hermes_gateway', 'restore_hermes_config', 'review_acceleration_trial', 'run_alert_sweep', 'run_alert_worker', 'run_calliope_procedure', 'run_sql', 'run_sql_multi', 'run_workspace_sql', 'save_workspace_job', 'schedule_calliope_thread', 'scoreboard', 'search_business_context', 'search_calliope_actions', 'search_data', 'search_hermes_docs', 'search_tools', 'semantic_enrichment_status', 'set_alert_cadence', 'set_alert_enabled', 'set_alerts_enabled', 'set_artifact_area', 'set_calliope_playbook_access', 'set_category', 'start_acceleration_trial', 'start_live_app', 'stop_live_app', 'sync_system_learning', 'system_learning_status', 'tanstack_chart_template', 'team_create', 'team_get', 'team_list', 'team_people_search', 'team_update', 'unmute_alert', 'update_calliope_page', 'update_calliope_sketch', 'update_chart', 'update_dashboard', 'update_live_app', 'update_map', 'upload_artifact', 'validate_hermes_config', 'validate_sql', 'wiki_list_pages', 'wiki_read_page', 'wiki_set_page_state', 'wiki_write_page', 'withdraw_proposal', 'workspace_job_status']::text[]);

-- SQL-facing syntax card so `capability_search('where does this table come from')`
-- points at find as well as data_search.
VALUES (
    'find',
    'cap_syntax',
    'rvbbit.find(query text, k int DEFAULT 10, opts jsonb DEFAULT ''{}'') → ranked hits + envelope  |  rvbbit.find_flat(query, k, opts) → one flat row per hit  |  rvbbit.find_json(query, k, opts) → one jsonb document',
    'One door into the data: fuses the dense (embedding), lexical (indexed tsvector + trigram) and literal-VALUES (rvbbit.value_index) seams by rank and attaches an envelope to every table, column or cube hit — lineage (source system, connection, load mode, last load), freshness (rows, last analyze, acceleration state, last crawl), usage (who queries it, 30-day touches), meaning (value-system domains, metrics, cubes and dashboards that read it) and a sample_sql to run next. A literal value ("Coast Dental", "Closed Won") returns the column that holds it with matched_values and a locator query. `degraded` names any seam that was off, so an empty result is never silently half a search. opts: {"kinds":[…],"schemas":[…],"seams":[…],"rerank":true (bge cross-encoder over the candidate pool, one Hutch call),"judge":true (Jev decision score per top hit: can it directly answer the ask?)}. Use before assuming a table or column name; use describe_table only after find has named the relation.',
    'SELECT rank, relation, "column", score, seams, adapter, last_load_at, rows_est, touches_30d, domains, dashboards, matched_values, sample_sql FROM rvbbit.find_flat(''student payment balance overdue'', 8, ''{"rerank": true}'')',
    'cheap',
    ARRAY['discovery','schema','catalog','lineage','provenance','freshness','usage','values','find table','where is','which table','rerank','judge']
)
ON CONFLICT (name) DO UPDATE SET
    kind = EXCLUDED.kind,
    signature = EXCLUDED.signature,
    description = EXCLUDED.description,
    example = EXCLUDED.example,
    cost_class = EXCLUDED.cost_class,
    tags = EXCLUDED.tags;

-- Rebuild the capability graph now: capability_search_stale() watches
-- operators/catalog/metrics/cubes/brains, not these two seed tables, so the
-- server's self-heal would not notice. Embedded when the embedder answers,
-- lexical-only otherwise; never fails the migration.
DO $$ BEGIN
    BEGIN
        PERFORM rvbbit.capability_crawl(true);
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'rvbbit: capability_crawl(true) failed (%); retrying lexical-only', SQLERRM;
        BEGIN
            PERFORM rvbbit.capability_crawl(false);
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'rvbbit: capability_crawl(false) failed (%); run SELECT rvbbit.capability_crawl() later', SQLERRM;
        END;
    END;
END $$;

-- ═══════════════════════════════════════════════════════════════════════
-- Refresh bookkeeping, the crawl trigger, and a status probe for humans
-- ═══════════════════════════════════════════════════════════════════════
-- find_refresh() learns a throttle and a log so every crawl path (serial
-- catalog_crawl_run on fresh installs, the parallel run, the registration
-- tick, the lens button) can trigger it through catalog_runs without
-- rebuilding the snapshots every two minutes. The old one-argument signature
-- is dropped so the defaulted call stays unambiguous.

CREATE TABLE IF NOT EXISTS rvbbit.find_refresh_log (
    id       bigserial PRIMARY KEY,
    ran_at   timestamptz NOT NULL DEFAULT now(),
    source   text,                       -- cron | crawl | manual | datarabbit | …
    forced   boolean NOT NULL DEFAULT false,
    result   jsonb
);

DROP FUNCTION IF EXISTS rvbbit.find_refresh(text);
CREATE OR REPLACE FUNCTION rvbbit.find_refresh(
    graph  text    DEFAULT 'db_catalog',
    force  boolean DEFAULT false,
    source text    DEFAULT 'manual')
RETURNS jsonb LANGUAGE plpgsql VOLATILE AS $fn$
DECLARE
    v_t0   timestamptz := clock_timestamp();
    v_out  jsonb := '{}'::jsonb;
    v_last timestamptz;
BEGIN
    SELECT max(ran_at) INTO v_last FROM rvbbit.find_refresh_log WHERE result ? 'elapsed_ms';
    IF NOT force AND v_last IS NOT NULL AND v_last > now() - interval '10 minutes' THEN
        RETURN jsonb_build_object('skipped', true, 'reason', 'refreshed within the last 10 minutes',
                                  'last_ran_at', v_last);
    END IF;
    BEGIN v_out := v_out || jsonb_build_object('dense_tier', rvbbit.pgvector_refresh_catalog_if_stale(graph));
    EXCEPTION WHEN OTHERS THEN v_out := v_out || jsonb_build_object('dense_tier', jsonb_build_object('error', SQLERRM)); END;
    BEGIN v_out := v_out || jsonb_build_object('relation_refs', rvbbit.relation_refs_refresh());
    EXCEPTION WHEN OTHERS THEN v_out := v_out || jsonb_build_object('relation_refs', jsonb_build_object('error', SQLERRM)); END;
    BEGIN v_out := v_out || jsonb_build_object('usage', rvbbit.usage_snapshot_refresh());
    EXCEPTION WHEN OTHERS THEN v_out := v_out || jsonb_build_object('usage', jsonb_build_object('error', SQLERRM)); END;
    BEGIN v_out := v_out || jsonb_build_object('lineage', rvbbit.relation_lineage_refresh());
    EXCEPTION WHEN OTHERS THEN v_out := v_out || jsonb_build_object('lineage', jsonb_build_object('error', SQLERRM)); END;
    v_out := v_out || jsonb_build_object('elapsed_ms', round(extract(epoch FROM clock_timestamp() - v_t0) * 1000),
                                         'source', source);
    DELETE FROM rvbbit.find_refresh_log WHERE id < (SELECT max(id) FROM rvbbit.find_refresh_log) - 200;
    RETURN v_out;
END $fn$;

-- Every crawl path finalizes a catalog_runs row; refresh the find snapshots
-- when one lands (same shape as 0199's capability crawl trigger). Never fails
-- the crawl.
CREATE OR REPLACE FUNCTION rvbbit._find_refresh_on_catalog_ok()
RETURNS trigger LANGUAGE plpgsql AS $trg$
BEGIN
    IF NEW.graph_id <> 'db_catalog' THEN
        RETURN NULL;
    END IF;
    BEGIN
        PERFORM rvbbit.find_refresh(NEW.graph_id, false, 'crawl');
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'catalog crawl: find_refresh failed (%) — run SELECT rvbbit.find_refresh() manually', SQLERRM;
    END;
    RETURN NULL;
END $trg$;

DROP TRIGGER IF EXISTS rvbbit_find_refresh_after_catalog ON rvbbit.catalog_runs;
CREATE TRIGGER rvbbit_find_refresh_after_catalog
    AFTER UPDATE OF status ON rvbbit.catalog_runs
    FOR EACH ROW
    WHEN (NEW.status = 'ok' AND OLD.status <> 'ok')
    EXECUTE FUNCTION rvbbit._find_refresh_on_catalog_ok();
ALTER TABLE rvbbit.catalog_runs ENABLE ALWAYS TRIGGER rvbbit_find_refresh_after_catalog;

-- One document describing the state of every seam and snapshot behind find:
-- what DataRabbit's Index panel shows and what an operator checks first when
-- a search looks thin.
CREATE OR REPLACE FUNCTION rvbbit.find_status(graph text DEFAULT 'db_catalog')
RETURNS jsonb LANGUAGE plpgsql STABLE AS $fn$
DECLARE
    v_graph   text := coalesce(nullif(btrim(graph), ''), 'db_catalog');
    v_dense   jsonb;
    v_lex     jsonb;
    v_values  jsonb;
    v_snap    jsonb;
    v_refresh jsonb;
    v_crawl   jsonb;
    v_pending int;
BEGIN
    v_dense := rvbbit.dense_seam_status(v_graph);

    SELECT jsonb_build_object(
               'indexed', to_regclass('rvbbit.catalog_docs_lex_gin') IS NOT NULL,
               'trigram', to_regclass('rvbbit.catalog_docs_doc_trgm') IS NOT NULL,
               'docs', count(*),
               'by_kind', (SELECT jsonb_object_agg(kind, n) FROM (SELECT kind, count(*) AS n FROM rvbbit.catalog_docs WHERE graph_id = v_graph GROUP BY kind) k))
      INTO v_lex
      FROM rvbbit.catalog_docs WHERE graph_id = v_graph;

    BEGIN
        SELECT count(*) INTO v_pending FROM rvbbit.value_index_candidates(5000);
    EXCEPTION WHEN OTHERS THEN v_pending := NULL; END;
    SELECT jsonb_strip_nulls(jsonb_build_object(
               'relations_ok', count(*) FILTER (WHERE status = 'ok'),
               'relations_skipped', count(*) FILTER (WHERE status = 'skipped'),
               'relations_error', count(*) FILTER (WHERE status = 'error'),
               'values', coalesce(sum(values_indexed) FILTER (WHERE status = 'ok'), 0),
               'columns', coalesce(sum(columns_indexed) FILTER (WHERE status = 'ok'), 0),
               'bytes', pg_total_relation_size('rvbbit.value_index'),
               'last_indexed_at', max(indexed_at),
               'pending', v_pending,
               'skipped', (SELECT jsonb_agg(jsonb_build_object('relation', schema_name || '.' || rel_name, 'reason', error) ORDER BY indexed_at DESC)
                             FROM (SELECT * FROM rvbbit.value_index_state WHERE status = 'skipped' ORDER BY indexed_at DESC LIMIT 5) s),
               'errors', (SELECT jsonb_agg(jsonb_build_object('relation', schema_name || '.' || rel_name, 'error', left(error, 200)) ORDER BY indexed_at DESC)
                            FROM (SELECT * FROM rvbbit.value_index_state WHERE status = 'error' ORDER BY indexed_at DESC LIMIT 5) e)))
      INTO v_values
      FROM rvbbit.value_index_state;

    SELECT jsonb_build_object(
               'refs', (SELECT jsonb_build_object('rows', count(*), 'relations', count(DISTINCT relation), 'as_of', max(refreshed_at)) FROM rvbbit.relation_refs),
               'usage', (SELECT jsonb_build_object('objects', count(*), 'as_of', max(refreshed_at)) FROM rvbbit.usage_snapshot),
               'lineage', (SELECT jsonb_build_object('relations', count(*), 'with_last_load', count(last_load_at),
                                                     'adapters', (SELECT jsonb_object_agg(coalesce(adapter, 'none'), n)
                                                                    FROM (SELECT adapter, count(*) AS n FROM rvbbit.relation_lineage GROUP BY adapter) a),
                                                     'as_of', max(refreshed_at))
                             FROM rvbbit.relation_lineage))
      INTO v_snap;

    SELECT jsonb_build_object('ran_at', ran_at, 'source', source, 'forced', forced, 'result', result)
      INTO v_refresh
      FROM rvbbit.find_refresh_log ORDER BY id DESC LIMIT 1;

    SELECT jsonb_build_object('run_id', run_id, 'status', status, 'finished_at', finished_at,
                              'tables_seen', tables_seen, 'docs_embedded', docs_embedded)
      INTO v_crawl
      FROM rvbbit.catalog_runs WHERE graph_id = v_graph ORDER BY run_id DESC LIMIT 1;

    RETURN jsonb_build_object(
        'graph', v_graph,
        'as_of', now(),
        'dense', v_dense,
        'lexical', v_lex,
        'values', v_values,
        'snapshots', v_snap,
        'last_refresh', v_refresh,
        'last_crawl', v_crawl,
        'degraded', (SELECT coalesce(jsonb_agg(x), '[]'::jsonb) FROM (
            SELECT 'dense: ' || coalesce(v_dense->>'reason', v_dense->>'tier') AS x WHERE NOT coalesce((v_dense->>'ready')::boolean, false)
            UNION ALL SELECT 'lexical: catalog_docs has no tsvector index' WHERE to_regclass('rvbbit.catalog_docs_lex_gin') IS NULL
            UNION ALL SELECT 'values: index empty (run CALL rvbbit.value_index_sweep())' WHERE coalesce((v_values->>'relations_ok')::int, 0) = 0
            UNION ALL SELECT 'snapshots: never refreshed (run SELECT rvbbit.find_refresh())' WHERE v_refresh IS NULL) d));
END $fn$;
