INSERT INTO rvbbit.capability_mcp_tools (name, summary) VALUES
('acceleration_steward_snapshot', 'Return the bounded canonical packet for acceleration judgment. This refreshes the observe-only workload classifier, then combines its candidates with mirror load mode/cadence, freshness, policy, runtime cost, recent operations, derived-layout recommendations, open trials, and prior receipts. It never enables or rebuilds a table.'),
('accept_proposal', 'Accept a pending cube/metric proposal directly and publish it now. The proposal queue is useful evidence and version history, not an approval gate. Optional fields refine the final object at acceptance time.'),
('administer_calliope_action', 'Install, configure, repair, or test one organization capability directly. This is the normal path for a signed-in Calliope administrator. Use an exact action id returned by `search_calliope_actions`. The tool creates its own durable, redacted audit receipt, applies the bounded change, actively tests it, and returns failed-step detail that can be used for a repair/retry. It never accepts credentials. If a required key is not already in the canonical store, it returns `secure_input_required` and the exact missing names so the user can enter only those values in the native secure form. Submitting'),
('administer_local_sql', 'Execute appliance-local RVBBIT SQL as the signed-in Calliope administrator. Use ordinary `run_sql` for analysis. Use this tool when the user asks Callie to create, alter, repair, or otherwise administer objects in her own RVBBIT PostgreSQL database. Normal data work belongs in calliope, app state in calliope_apps: prefer run_workspace_sql for atomic batches without approval. Workspace-targeted writes submitted here automatically use that same path. Outside that workspace, one SELECT/WITH-shaped statement executes directly on the writable local connection, including RVBBIT table functions that '),
('agent_overlay_list', 'List agent overlays (SOUL/skill learned blocks) with state and audit context. Filter by agent_key or adoption state (''proposed'' = behavior overlays awaiting operator adoption).'),
('agent_overlay_propose', 'Propose a learned overlay block for an agent''s SOUL (''soul'') or one of its skills (''skill'' + target_key). kind=''knowledge'' (additive facts/gotchas — adopts provisionally at once) or kind=''behavior'' (changes how the agent acts — waits for explicit operator adoption). The overlay composes beneath the repo baseline at the next reconcile; it never edits the baseline. A body identical to a previously rejected/demoted overlay is refused with the prior reason — revise it against that reason instead of re-proposing.'),
('agent_overlay_set_state', 'Adopt (''auto_provisional''), affirm, demote, retire, or reject an overlay. Adopting a ''proposed'' behavior overlay is the operator gate; rejections record the reason into the audit ledger so the same idea cannot be silently re-proposed. Adopted overlays reach the agent at the next Hermes reconcile (container restart or deploy).'),
('alert_events', 'The firing audit log (newest first): which rule+entity fired, the transition, fired/failed status, the action output or error, and when. Pass name to scope to one rule.'),
('alert_state', 'Per-entity reconciler state for a rule: entity_key, last_status (pass|fail), score, consecutive fail count, and when it last changed/fired — the breakdown behind a rule''s breach count.'),
('alert_sweep_runs', 'The sweep heartbeat (newest first): per tick — tier, start/finish, rules evaluated, transitions, enqueued, errors. Use it to confirm the reconciler is alive and see its rate.'),
('apply_hermes_config', 'Validate and queue a secret-free Hermes configuration revision. Admin-only mutation. The call returns before Hermes restarts. An independent controller resolves canonical credentials in memory, restarts the gateway, verifies its API, command catalog, and Warehouse bridge, and automatically restores the last-good YAML if verification fails. This is direct appliance administration and needs no separate plan ceremony.'),
('approve_calliope_playbook', 'Approve the latest owned Playbook draft for capability discovery. Call this only after the human explicitly confirms the reviewed version. Approval moves the searchable pointer atomically; immutable older versions and their provenance remain available to the owner.'),
('archive_calliope_page', 'Archive a caller-owned living Page when requested. Read first and pass its definition_version. Preserves revision history and archives its notebook; refuses while refreshing. Does not delete or change source documents.'),
('archive_calliope_playbook', 'Archive or restore an owned Playbook without deleting its history. Archive removes the approved projection from discovery for everyone. Restore reinstates the same approved version and prior audience.'),
('artifact_access_get', 'Inspect sharing for one artifact you own. Returns the optimistic-lock revision, selected Teams and people, available Teams, and recent access receipts. Readers cannot inspect its audience.'),
('artifact_access_update', 'Replace an owned artifact''s complete viewer list atomically. Inspect first with artifact_access_get and send its expected_revision. Team IDs and observed human emails are exact desired lists, not deltas. The owner always retains access implicitly. Setting the Everyone Team for the first time requires confirm_everyone=true.'),
('artifact_archive', 'Archive an artifact you own without deleting versions, grants, or history.'),
('artifact_restore', 'Restore an owned archived artifact with its prior viewer grants intact.'),
('ask_brain', 'Semantic search over visible COMPANY BRAIN / DOCUMENT STORE contents. Use this for documents, Linear/Jira tickets, meeting notes, policies, and other indexed knowledge. Resolve exact visible source/type labels with brain_facets, then pass filters such as {"source": "Linear Issues", "type": "ticket"}. Returns grounded chunks to cite, not a synthesized answer. For broad synthesis, make a few distinct filtered searches and deepen useful hits with brain_context, brain_get_doc, or brain_related.'),
('ask_calliope', '(Specialists only) Send a precise question back to Calliope, then end this round. Use this when the assignment cannot be completed well without a decision that belongs to Calliope or the human — an unstated scope, a choice between two defensible framings, missing access — and the answer would change what you build. It queues the question for delivery to Calliope''s conversation (she sees it as an [AGENT MESSAGE] and answers on this same thread), and it does not wait: after calling it, finish this round now with a short status of what you have so far and what you will do once answered. Do not as'),
('ask_system_learning', 'Ask what RVBBIT has learned about this database. This is the agent-safe shortcut over ask_brain(filters={"type":["system_learning"]}) so callers do not need to remember the doc_type name. Results include workload/layout/routing/acceleration/operator breadcrumbs, not a synthesized answer. Compose an answer from the returned chunks and cite titles.'),
('await_calliope_specialists', 'Block once for the outcome of async specialist rounds you started earlier. Use this only when the very next step of this turn genuinely depends on a reply you delegated with mode="async" and you have nothing else useful to do; the normal path is to end the turn and let the reply arrive as an [AGENT MESSAGE]. Pass the thread_ids (or run_ids) you were given. Returns each round''s result once it ends, acknowledging its queued reply when called by the original parent so it is not delivered again. Returns current status when timeout_seconds passes. Never call this in a loop.'),
('begin_calliope_work_order_run', 'Begin one approved private Calliope assignment occurrence. This lifecycle tool is only for the managed Hermes prompt created when the owner activates an assignment. Pass its exact work-order, source-session, definition-version, and Hermes-job values. The server validates the binding, skips overlapping runs, creates a fresh private run notebook, and returns the immutable execution contract. Finish every successful begin exactly once.'),
('begin_calliope_workflow_run', 'Begin one approved headless Calliope Workflow run. This lifecycle tool is for the Hermes schedule prompt produced by Calliope. Pass the exact workflow UUID, originating Calliope session UUID, and approved version embedded in that prompt. It validates the publication pointer, creates a fresh paired run notebook, freezes the graph and governed context, and returns the sole execution contract. Do not improvise IDs or call it for an unpublished draft. Finish every successful begin with exactly one `finish_calliope_workflow_run` call.'),
('bind_calliope_term', 'Bind a company term to its canonical referent in the Resolution Ledger. Use when a person TEACHES what a business word means here ("when we say Leads we mean enrollment leads in Salesforce") — never to record your own guesses; taught meanings are denominators, and they belong in canon, not memory. Actions: ''bind'' writes a stipulated binding — pass `term` (the word people say), `referent_kind` (''metric'' | ''relation'' | ''artifact''), `referent` (metric name, schema.relation, or artifact slug — must exist), and a one-sentence `gloss` stating the settled meaning. ''list'' shows the live ledger. ''inval'),
('brain_browse', 'Browse a bounded page of visible Company Brain tree metadata. This is for folder/file navigation only. It does not search document text, and an incomplete or empty page is never evidence that a source/document is absent. Use brain_facets + ask_brain for corpus questions.'),
('brain_context', 'Read nearby chunks from a visible Brain document, including the selected private Doc.'),
('brain_crawl_folder', 'MUTATING INGESTION TOOL — import files from an allowed SERVER folder. This never searches or browses the existing Company Brain. Call only when the user explicitly requests a folder import. The path must be beneath WAREHOUSE_BRAIN_IMPORT_ROOTS; broad roots such as `/` are always rejected, and an explicit source label is required.'),
('brain_entity', 'Retrieve visible Company Brain evidence connected to one named entity.'),
('brain_exclude', 'MUTATION: exclude one principal from one Company Brain document.'),
('brain_facets', 'List visible Company Brain document types and source labels with counts. Call before ask_brain whenever a user names a corpus, connector, or document class such as Linear tickets and the exact stored source/type is uncertain.'),
('brain_get_doc', 'Open one visible Brain document; selected private Calliope Docs are turn-scoped.'),
('brain_grant', 'MUTATION: grant or revoke one principal''s Company Brain access role.'),
('brain_ingest', 'MUTATION: ingest one supplied document into a named Company Brain source. This does not retrieve or search existing documents. Use only when the user asks to add content; omitted roles retain the source defaults/default-deny.'),
('brain_related', 'Traverse a visible Brain document''s neighborhood with selected-Doc turn scope.'),
('brain_set_doc_roles', 'MUTATION: replace the Company Brain access-role set for one document.'),
('breaching_alerts', ''),
('breaching_kpis', ''),
('business_context_changes', 'Explain how the interpreted business model changed between versions. Returns source, metric, dimension, formula, grain, time-semantics, and value relationship changes. Pending candidates never replace promoted canonical logic automatically, and retained source SQL is not disclosed.'),
('business_context_for_question', 'Inspect the promoted business map automatically available to this question. This is the notebook''s ordinary-chat preflight packet: relevant Value Systems when matched, otherwise a tiny ambient map so useful concepts can surface without the human knowing their names. Source SQL is never included.'),
('business_context_status', 'Check whether Calliope''s interpreted business model is current. Returns cheap structural-fingerprint freshness, dirty reasons from mirrors or catalog crawls, durable topology work, and the latest Change Graph state. Use this before claiming the business model reflects a newly changed schema.'),
('business_metric_change', 'Explain a promoted metric''s change through one validated contributor. Use the governed metric name and a dimension key returned by Business Context. Periods are half-open ISO timestamp ranges. This is the preferred attribution path over rebuilding joins and arithmetic from raw tables.'),
('calliope_decision_request', 'Create or revise one evidence-backed decision for the originating user. Use only when a current ranked Calliope observation leads to a bounded human judgment. `session_id` is the exact UUID supplied in the Calliope work-routing context; `observation_id` is an active observation UUID the user can inspect. Use calliope_observation_context first unless the exact observation receipt is already present. Supply 2-6 options, each with a lowercase `key`, `label`, and optional `summary` / `consequence`. Use `recommended_option` only when the evidence supports it. The same open observation is revised in'),
('calliope_observation_context', 'List the current user''s ranked observations that may warrant a decision. `session_id` must be the exact Calliope UUID supplied in the current turn''s work-routing context. Identity is resolved from that session; this tool has no recipient argument. Prefer evidence-bearing `lead` / `supporting` rows marked `decision_ready`. Pass the chosen exact observation `id` to calliope_decision_request; do not manufacture an id or decide from a row the user marked not relevant.'),
('calliope_session_access_get', 'Inspect read sharing for an ordinary Calliope chat notebook you own. Returns its optimistic-lock revision, selected Teams and observed people, available Teams, audience summary, and recent append-only access receipts.'),
('calliope_session_access_update', 'Replace an owned Calliope notebook''s audience and participant permissions. Inspect first and send its expected_revision. Team IDs and observed human emails are exact desired lists, not deltas. The owner remains implicit and alone manages sharing, renaming and archiving. Add emails from people to participants to let them converse under their own identity and tool authority. Pass participants=[] for view-only; omitted preserves retained roles. Teams are view-only. Adding Everyone for the first time requires confirm_everyone=true.'),
('calliope_sheet_query', 'Join a selected private Google Sheet to governed warehouse SQL. The default read_mode=snapshot exposes the immutable Stage snapshot only inside this call as a typed relation named ``selected_sheet``. Use read_mode=live only when the user explicitly asks for current/latest/live Sheet values; it performs one bounded Google API read but does not replace the saved Stage snapshot. Use the exact ``sql_name`` fields supplied in the selected-surface context or by ``calliope_sheet_snapshot``. The statement must be one read-only SELECT/CTE and reference ``selected_sheet``; ordinary warehouse relations m'),
('calliope_sheet_snapshot', 'Page through the private frozen Google Sheet explicitly selected for this Calliope turn. Pass the exact surface_id from CALLIOPE_SELECTED_SURFACE. Rows and columns are bounded; advance offset or column_offset to inspect more of a large snapshot. This never reads the live Google file and cannot open an unselected or another user''s Sheet.'),
('calliope_work_item', 'Publish a genuine unresolved human blocker to the originating user''s inbox. Use kind=blocked only. Routine results, completion recaps, proactive ideas, schedule announcements and goals do not create notifications: the tool returns published=false and the tool-call audit receipt remains. The current chat and Stage already deliver interactive work, including delegated work. Managed background runs deliver through their finish tool and saved notification policy; do not duplicate those deliveries here. Curated Dreams handle proactive ideas. session_id must be the exact Calliope session UUID from i'),
('capability_search', 'Search WHAT THIS WAREHOUSE CAN DO — the same just-in-time discovery the built-in assistant uses: semantic SQL operators (means()/about()/extract/ classify/forecast/...), installed MCP servers and their tools, installable capability packs, SQL syntax patterns, models and providers. Ask in plain language ("extract entities from text", "search the web", "forecast this series") and get callable names + signatures back — operators are directly usable inside run_sql and approved Playbooks can be loaded as reusable methods. Hermes procedural skills are compact cap_skill stubs; load the exact body wit'),
('capture_live_app', 'Capture a PNG screenshot of a live app. Omit path for normal use. path is an OUTPUT IMAGE FILENAME (.png/.jpg) on the server, NOT a URL or /apps/ route; the receipt always returns a separate retained capture so filename reuse cannot replace it. slug identifies the page. Capture the final published version. HTML captures inject the live rvbbitQuery bridge and wait for all queries to settle. data_timeout_ms optionally sets the HTML data wait (500–60000ms; default 60000ms, configurable by the host). wait_ms is a separate post-readiness paint delay. verification.status distinguishes ready, no_quer'),
('compare', 'Period-over-period / variance for a metric: its value at period_a vs period_b with Δ and %Δ. Pass `by` (a cube dimension) to break it down per segment (a variance table). Periods are data-time instants (e.g. ''2026-03-31'' vs ''2026-06-30'') — each side is the metric AS OF that instant via the bitemporal engine. Render the breakdown as a table sorted by |Δ|.'),
('connect_mirror_source', 'Connect/reuse a managed SQL source from any chat; no setup wizard required. connection_name is a stable lowercase name (3–63 characters). dialect is postgresql, mysql, mariadb, mssql, oracle, db2 or bigquery. An existing enabled source with credentials is reused without replacing them. Otherwise a native secure SOURCE_DSN field appears on the Stage. Direct the user there; NEVER ask for a DSN/password in chat or pass it to a tool. Native submission saves and probes the source with a durable receipt, without another approval. Then discover_mirror_source lists schemas/tables for create_mirror_job'),
('continue_calliope_specialist', 'Continue a real, multi-round conversation with a specialist agent. Send Calliope''s next argument, correction, question, or request to the same Hermes session. The specialist retains the entire thread and its separate Hindsight memory. Prefer this over opening another delegation when the specialist''s first answer deserves challenge, verification, refinement, or an adversarial review. When the user asks for debate, critique, red-teaming, or a second opinion, do not stop after the first specialist reply: continue the thread with the unresolved point and integrate the resulting exchange. This is a'),
('create_calliope_page', 'Create a private living Page for the caller, with its own reusable notebook. question is the enduring question; standing_brief describes sections, emphasis and scope. anchor_label optionally names a project/person/topic for evidence. Returns the Page link and a refresh_contract of caller-visible source evidence. Write the first revision HERE using finish_page_refresh and that contract''s run_id and [N] citations. Do not spawn a second agent or use wiki/SQL/file tools to save it. Missing evidence leaves a saved empty Page with refresh_error. Retrying the same title in this turn reuses the Page. '),
('create_calliope_sketch', 'Create the one collaborative visual Sketch in a Calliope notebook. The surrounding Calliope web-notebook prompt may authorize proactive use; in other clients, use this only after an explicit human request. A process, system map, comparison, spatial explanation, or evolving set of ideas is a good fit when it communicates better visually than prose and does not need a dashboard. `session_id` must be the exact originating Calliope session. `operations` is a strict, discoverable union of typed edits. add_shape.label and connect.label render as bound text that follows its element; `text` is also ac'),
('create_cube', 'Create and materialize a governed cube directly from validated SELECT SQL. This is append-versioned and reversible; use edit_cube for later versions. No DataRabbit approval ceremony is required.'),
('create_live_app', 'Create a versioned RVBBIT live app. HTML apps are hosted immediately at /d/<slug> and call rvbbitQuery(sql) for live, read-only data. For editable HTML apps, publish manifest.actions and call rvbbitAction(name, inputs): versioned, bound SQL transactions writing calliope_apps or calliope tables, without a separate backend or per-click approvals. Publication automatically queues a separate semantic compiler pass; new apps are private to their verified human owner until shared. An authored manifest.semantic_map remains an optional precise hint. Accepts inline html or an upload_artifact handle via'),
('create_metric', 'Create a governed scalar metric directly after executing a bounded proof. The resolved SQL must return exactly one row. Definitions are append-versioned; a first observation is materialized by default. No UI approval is required.'),
('create_mirror_job', 'Create an on-demand managed SQL mirror from an existing SQL connection. Supply description: one plain-language sentence explaining purpose and tables maintained. Call connect_mirror_source and discover_mirror_source first if needed. tables is an array of mappings: source_table (required), destination_table (optional), load_mode (snapshot default, or incremental_upsert), primary_key (column-name array), cursor_column, included_columns (optional array), and change_detection (always default; append_only_key ONLY for immutable rows). Incremental upsert needs primary_key and a trustworthy update cu'),
('cube_pivot', 'Explore a cube directly as a grouped table or crosstab, without requiring a metric. ``rows`` and optional ``cols`` accept one field or a list of fields. ``measures`` accepts ``[{field, aggregate}, ...]`` and supersedes the legacy singular ``measure``/``aggregate`` pair. With no column dimensions the result is an ordinary grouped table. Adding column dimensions produces a crosstab. Every relation and field is validated and quoted.'),
('curate_calliope_memory', 'Curate the long-term memory bank when a stored fact is corrected. Use ONLY when a person explicitly corrects something you recalled or asserted from memory ("no, we switched processors in July", "that is not Michael''s role anymore") — never to editorialize your own beliefs unprompted. Workflow: action ''find'' with a `query` locates candidate memory units (id, type, text); action ''invalidate'' with `memory_id` and a `reason` naming who corrected it and what they said soft-retires the stale unit — it leaves recall and consolidation but is kept for audit and is reversible via action ''revert''. Never'),
('dashboard_crawl', 'Re-extract a dashboard''s data dependencies (queries → tables, metrics) into the catalog index — runs the LLM pass + reconciles the queries it actually ran.'),
('dashboard_dependents', 'Impact analysis: which dashboards depend on a given table or metric.'),
('dashboard_template', 'Return the proven drop-in boilerplate for a LIVE dashboard (Cowork artifact + hosted). In a hosted Calliope turn, its snapshotted authoring mode selects Dashboard widgets or free-form HTML; follow the returned template and how_to_use over legacy library advice. External Cowork retains its current template. ALWAYS start a dashboard from this — it has the data bridge, single-round-trip query pattern (composePayload), semantic-object binding helper, formatters, and chart/table wrappers already solved. Adapt its two `>>> EDIT` blocks and publish normally; the semantic compiler runs after publicati'),
('debug_live_app', 'Inspect and refresh a live app''s health: dependency crawl, recent query errors, runtime status, and recommended next actions.'),
('decide_workload_layout', 'Accept or reject one learned cluster/Hive layout recommendation.'),
('delegate_all_calliope_specialists', 'Invite every active Calliope specialist into one parent turn concurrently. Use this exactly once when the human writes @all or explicitly asks for every specialist''s independent position. Calliope herself is the coordinating parent and is not included. Every child inherits the same recent parent conversation, current-turn objects, selected evidence, attachments, surface, and design profile. The returned results are ordered by specialist display name and each represents a real persistent agent thread. Do not follow this with individual opening delegations merely to count, repeat, or confirm the'),
('delegate_calliope_specialist', 'Delegate one bounded assignment to a persistent Calliope specialist. mode="sync" (default) waits for the round and returns the specialist''s reply. mode="async" returns at once with the thread_id; the reply arrives later in this same conversation as an agent message — a turn that begins with [AGENT MESSAGE] — once the round ends, whether or not this turn is still running. Choose async when you have independent work to do meanwhile (write the narrative, self-check, run other queries, ask another specialist), when the round may be long, or when the user asked to be updated as results come in; cho'),
('describe_table', 'Full profile of one table: columns, live samples, AND per-column stats — null %, distinct count, and the actual most-common values (the enum/value dictionary, so you never guess a status/type literal) — plus freshness. Pass lean=true for a compact view (columns + null%/distinct + freshness, no samples or top-values) on wide tables to stay under the token budget.'),
('discover_mirror_source', 'Inspect a configured SQL source through the managed DLT worker. Omit source_schema to list schemas; supply it to list tables, columns, primary keys and suggested destination names (up to 500 tables, with a truncation flag). This is source metadata discovery, not a data load. connect_mirror_source handles new credentials through the native secure UI. Use create_mirror_job with the discovered names; mirror_status lists local jobs, schedules, run receipts and errors without contacting the source.'),
('draft_calliope_instrument', 'Draft or revise a safe declarative UI skill in the user''s Instrument library. Use this only after a user asks to make a repeatable workflow reusable, or a proactive task has strong evidence that a small form would remove repeated work. `session_id` must be the exact originating Calliope session UUID from the internal work-routing context; it resolves ownership and this tool accepts no recipient. Fields are declarative objects using text, textarea, number, select, boolean, or date. `prompt_template` may reference them as `{{field_key}}`. No HTML, JavaScript, SQL execution, or auto-publication i'),
('draft_calliope_playbook', 'Draft a private reusable Playbook from successful Calliope work. A Playbook captures the outcome, applicability, intent-level method, guardrails, and completion evidence—not a fixed sequence of tool calls. Use the exact source Calliope session and source_turn_id supplied by the Calliope web notebook; Warehouse pins the bounded turn range, Stage outputs, artifact versions, and optional current Sketch revision itself. New Playbooks are private and unsearchable until their owner explicitly approves a version. To revise one, read it first and pass its latest expected_version; the currently approve'),
('draft_calliope_work_order', 'Draft private work assigned to Calliope for later or recurring execution. Use the exact originating Calliope session UUID; ownership is resolved from that server-side capability. A draft never schedules itself. `schedule` uses Hermes syntax: an ISO timestamp or duration for one-time work, and `every …` or five-field cron for recurring work. Recurring schedules currently use the Hermes installation timezone. `notification_policy=attention` keeps healthy unchanged runs out of Work Inbox while preserving their run notebooks. The default read-only approval policy permits research and analysis, not'),
('draft_calliope_workflow', 'Draft or revise a bounded, agent-driven Calliope Workflow. Use this after the user wants repeatable work to run headlessly or on a schedule. `session_id` is the exact originating Calliope session UUID and resolves ownership. A Workflow has one manual/schedule trigger, up to eight governed context nodes (`artifact`, `semantic_object`, `evidence`, `knowledge`, or `instruction`), one agent goal with optional decision rules, and `stage`, `work_inbox`, or `artifact` outputs. Hermes dynamically chooses tools at run time; do not encode SQL, JavaScript, shell commands, or low-level tool nodes. Optiona'),
('edit_cube', 'Edit an existing cube''s DEFINITION in place — appends a new version (revert via the prior version) that goes LIVE immediately. Shape-aware: a column change rebuilds the cube table, a filter-only change preserves its AS-OF history. sql is required (the full new SELECT).'),
('edit_metric', 'Edit an existing metric IN PLACE — appends a new version (old versions are kept, so it''s reversible) that goes LIVE immediately. Only the fields you pass change. check_sql: omit to keep the current check, pass "" to remove it. Use this to fix/improve a metric you (or someone) defined.'),
('enrich_live_app', 'Queue semantic enrichment for an older or failed artifact version. New HTML versions are queued automatically; this tool is for backfills and explicit retries, not normal publishing.'),
('export_to_google_sheets', 'Run a governed read-only query and export its result to the user''s Google Sheets. Use the exact `session_id` from Calliope''s internal work-routing context; it resolves the owning human and their private Google Workspace grant, so this tool intentionally accepts no email, access token, or recipient. SQL passes through the same validation, read-only transaction, row cap, and database-role boundary as `run_sql`. The result is a durable export receipt plus a Google Sheets URL. If Workspace is not connected, direct the user to the native `Sheet` action on any query result; it performs the increment'),
('extract_image', 'Vision extraction for intake workflows: read an image (staging or capture volume — texted photos land there via the agent) and pull the named fields with a multimodal model. Returns strict JSON per field plus _confidence 0-1 each; low confidence is the caller''s cue to ask for a better photo ("can''t read the serial — shoot it closer").'),
('find', 'Find warehouse tables, columns, cubes, and literal values by meaning — with receipts. Use this first for "where is X / which table holds Y / do we have rows mentioning Z". Every hit carries lineage (source system, connection, load mode, last load), freshness (live rows, last analyze, acceleration state), usage (how often people query it), meaning (value-system domains, metrics, cubes, and dashboards that read it), and a sample_sql to run next. A literal value ("Cleveland Family Dental Center", a status code) returns the column that holds it plus matched_values. `degraded` lists any search seam'),
('finish_calliope_work_order_run', 'Finish one managed assignment and apply its notification policy. Call exactly once after a successful begin. Report only user-visible steps, never hidden reasoning. For a healthy recurring check with no meaningful change, set both `attention_required` and `changed` false; the result remains in its run notebook but `attention` notification policy will not clutter the Work Inbox. Exact artifact refs are verified against the owner''s access.'),
('finish_calliope_workflow_run', 'Finish one Calliope Workflow run and publish its durable result. Call exactly once after a successful `begin_calliope_workflow_run`, or when a manually opened Workflow supplies an exact run UUID. Status is `complete`, `blocked`, or `failed`. Include concise evidence-backed details and exact artifact refs/versions where applicable; unverified artifact claims remain visibly unverified. This closes the run notebook, adds result surfaces, records caller-attributed cost state, and publishes the user''s Work Inbox result or blocker. It is idempotent for an already-finished run.'),
('finish_page_refresh', 'Finish a requested living Page refresh. First read_page_refresh. outcome is updated (complete Markdown body with supplied [N] citations), unchanged (verified current), or incomplete (cannot verify). summary describes material changes or the reason for no update. Retains the previous revision on incomplete work. Source access, source versions, initiating turn and standing brief are checked before save. This tool only saves the Page; it does not authorize source-system mutations.'),
('generate_image', 'Generate an image with the configured provider; returns its URL and Stage metadata. Write the full visual prompt; no house style is added. Optional title names the image for Stage discovery; purpose describes its use (e.g. dashboard mockup, illustration, reference). Both have automatic defaults. Sizes: 1024x1024, 512x512, 1792x1024, 1024x1792. The saved generation brief describes requested content, not verified image contents or approval status.'),
('get_alert', 'One alert rule in full: latest-version condition_spec/action_spec/fire_policy, cardinality, fan-out cap, control state (enabled/muted/cadence), category, version history, a live state summary (breaching/entities/pending, last fired), and its most recent firing events.'),
('get_business_value_system', 'Open one receipt-backed Value System and its formulas, contributors, and proof. Accepts the value_system handle returned by search, or a graph UUID, domain, governed metric name, or cube name. Proposed systems are evidence only; promoted systems return the canonical metric and cube handles to execute. Source event SQL is hash-referenced by default; include_sql=true is for definition debugging when the formula, dimensions, and lineage are insufficient.'),
('get_calliope_personal_context', 'Read the Workflow owner''s latest private Brief, notes, and Work Inbox. The exact Workflow run UUID is an opaque capability: ownership is resolved server-side and there is intentionally no email or user parameter. Use this only when the frozen Workflow goal requires the owner''s personal Calliope context. Resolved Inbox items may be included to avoid duplicate follow-up.'),
('get_calliope_work_order_personal_context', 'Read the assignment owner''s latest private Brief, notes, and Work Inbox. The exact assignment run UUID is the opaque capability; there is no email argument and ownership is always resolved server-side. Use this only when the returned assignment contract says the owner''s personal context matters.'),
('get_dashboard', 'Fetch a dashboard''s metadata, source, and data dependencies (to inspect or fork it). part=''source'' returns version and HTML together for expected_version-checked edits. part=''html'' returns just the version''s source as plain text (copy edit targets from it); part=''structure'' returns only the heading/element-id inventory.'),
('get_live_app', 'Fetch a live app''s metadata, manifest, versioned source, dependencies, and recent query calls. part=''source'' returns version and HTML together for expected_version-checked edits. part=''html'' returns just the version''s html as plain text — the cheapest read before update_live_app(edits=…), and the text to copy `find` targets from; part=''structure'' returns only the heading/element-id inventory.'),
('get_metric', 'One metric''s definition, history, and attached Business Context.'),
('get_proposal', 'Full detail of one proposal — sql, grain, source_tables, params, check_sql, join_rationale, confidence, status, result_name. Use after list_proposals to inspect a specific draft.'),
('get_tool_help', ''),
('hermes_config_current', 'Read the active secret-free Hermes YAML and its canonical secret bindings. Admin-only. The returned binding values are credential references, never plaintext credentials. Read this, search the pinned docs, make the smallest edit, then validate or apply it.'),
('hermes_config_status', 'Inspect Hermes supervisor health and secret-free config revision history. Admin-only. This is the recovery and observability view; raw YAML is omitted from historical rows.'),
('kit_rehearsal', 'The rehearsal (a LINT, never the source): compile the kit''s deterministic briefing (rvbbit.kit_brief), hand it to a model with a scenario, and get back (a) the step-by-step runstream it would follow and (b) every AMBIGUITY or MISSING VERB it had to guess around. The gap list is the payload — each finding is either an edit to a logic plate''s explanation or an action the kit still needs.'),
('list_alerts', 'Alert rules with live vitals: each rule''s condition/action shape, on/off + mute + cadence tier, and current breach/entity/pending counts + last-fired. The agent''s entry point for "what''s firing and why". Filters: category, enabled (bool), muted (bool), tier (fast|normal|slow), search (name/description). Also returns the global alerts_enabled kill-switch state.'),
('list_artifact_areas', 'List the controlled Artifact Areas used to organize the Gallery without one-off categories.'),
('list_calliope_pages', 'Find the caller''s private living Pages by title or enduring question. Returns IDs, notebook session IDs, revision and refresh status. Not the shared agent wiki.'),
('list_calliope_specialist_threads', 'List the current user''s durable specialist conversations. Use this to resume an earlier collaboration after context compaction or a later Calliope turn. Threads are agent conversations, not tool receipts. Compact previews by default (detail=''summary''); detail=''full'' keeps the longer objective and latest_reply text. thread_id is what continue needs.'),
('list_calliope_specialists', 'List the persistent specialist profiles Calliope may delegate to. Specialists are bounded collaborators, not alternate Company Brains. Each has isolated Hermes sessions, skills, and Hindsight working memory. The managed roster and preferred ownership rules are already in Calliope''s instructions, so normal delegation does not require this lookup. Use this tool to inspect live availability or discover newly added specialists.'),
('list_cubes', 'Curated subject-area tables (cubes) — wide, documented, accelerated, with their category. The agent''s entry point: look here (and at metrics) before raw tables. Optional `category` filter.'),
('list_dashboards', 'List published dashboards (optionally filter by team or a name/description search).'),
('list_live_apps', 'List versioned live apps with runtime kind, health, dependency counts, and URLs. Compact rows by default (detail=''summary''); pass detail=''full'' to inline each app''s manifest, query traces, and semantic objects, or use get_live_app(slug) for one app.'),
('list_metrics', 'The blessed, governed metric catalog (latest version per metric), with its category. Read from metric_catalog (not metric_defs) so the shared category/subcategory taxonomy is included — use the optional `category` filter to scope to one subject area.'),
('list_proposals', 'See the proposal queue — drafts (yours or others'') and their fate. Filter by status (pending/accepted/rejected/withdrawn), kind (cube/metric), or proposed_by. ACCEPTED proposals carry result_name (the object created); REJECTED/WITHDRAWN carry notes (the reason). Use this to LEARN from feedback before proposing again — don''t re-propose something already rejected, and refine_proposal a pending draft instead of submitting a duplicate.'),
('list_specialist_findings', 'List compact shared findings from persistent Calliope specialists.'),
('live_app_logs', 'Return recent live-app query events from mcp_activity for debugging.'),
('live_app_status', 'Inspect local live-app runner state for one app or every running app.'),
('live_app_template', 'Return a starter live-app contract. Use html for immediately hosted apps; use python-fastapi to scaffold source that is stored, versioned, and runnable under local uvicorn. HTML includes a complete editable task app example: calliope table setup, typed manifest.actions, rvbbitAction calls, conflict handling and retry semantics.'),
('look_at_desktop', 'Look at the shared Desktop Lab desktop open in this thread. Read-only. Captures the current screen and returns it as native image input beside the workbench state (who is driving, Guided Run phase). Use it whenever the person refers to what is on their desktop, asks what you see, or before advising on a screen; describe only what the returned image shows. This never takes the lease, never sends input, and never approves anything: acting on the desktop happens only inside a Guided Run through propose_calliope_computer_action. Pass the current thread''s session_id; workbench_id is optional when t'),
('manage_workspace_job', 'Pause, resume or run_now a saved SQL ETL job without a reasoning session. pause disables scheduled and queued runs; an already running bounded batch finishes. resume enables the saved interval, with first run one interval from now. run_now queues one execution even for a paused/manual job, without enabling its schedule. Repeated requests coalesce; a running job is not queued again. Inspect failed/interrupted run receipts and external MCP effects before retrying: database rollback cannot undo an external tool''s effects.'),
('materialize_metric', 'Snapshot a metric NOW into the durable observation log (value + KPI verdict at this instant) — the basis for trend history and breach monitoring. Returns the observation id.'),
('metric', 'A blessed, governed scalar number — bitemporal (as_of = data-time, def_as_of = def-time). Pass group_by (a list of cube dimension columns) to slice a DIMENSIONAL metric — one defined over a cube (labels.cube_source) — into a breakdown row per group (e.g. group_by=[''stage_name'']). The metric''s measures are reused verbatim; dimensions are validated against the cube''s real columns. Call metric_dimensions(name) to discover which columns are sliceable.'),
('metric_dimensions', 'The cube columns a DIMENSIONAL metric can be sliced by (empty unless it declares labels.cube_source). Each entry: column, type, kind (dimension/time/key/measure), groupable. Feed groupable columns to metric(name, group_by=[...]) for a breakdown.'),
('metric_history', 'The durable observation series for a metric (newest first): value, KPI verdict/status, the data-time it was taken at, and how it was triggered. Turns a definition into a trend.'),
('metric_lineage', 'The base tables a metric reads (for impact analysis) — resolved from its SQL via the planner. The metric-side mirror of dashboard_dependents.'),
('mirror_status', 'Inspect managed DLT: connections, job index, schedules, health and run history. With no filters, return configured connections/jobs and recent runs. Pass job_name for its configured tables, load modes, keys/cursors and recent runs; pass run_id for individual table outcomes, loaded rows and errors. limit is the recent-run count (1–100, default 10). These are durable local receipts, readable even when the worker is offline. No bespoke inspection SQL needed. Installed runtime, worker health, and configured jobs are separate facts; zero jobs does not mean DLT needs installation. This inspects mana'),
('mute_alert', 'Temporarily silence a rule''s ACTIONS without stopping evaluation. minutes=None mutes indefinitely (until unmuted); otherwise for that many minutes. Returns the muted_until.'),
('pivot', 'A governed crosstab of a DIMENSIONAL metric: rows (a cube dimension) × cols (a cube dimension) × one measure, with row/column/grand totals. Reshapes metric_by into a matrix — values are the blessed metric''s, dimensions are validated against the cube — so it''s a repeatable pivot table, not hand-rolled SQL. measure defaults to the metric''s first numeric measure. Call metric_dimensions(metric) to see the sliceable columns. Render as a matrix.'),
('preview_alert_condition', 'Dry-run an alert CONDITION read-only — the observable feedback for authoring a rule before any rule exists. Runs the query (LIMIT 500) and returns its (entity_key, score, status) rows + counts. If expr is given, wraps the query in the same CASE the sweep uses (status=''fail'' when expr true) so a bad boolean expr surfaces as an error here. A condition query should return an entity_key column plus EITHER a status (''pass''/''fail'') OR a numeric score. Read-only: writes are blocked.'),
('preview_metric_observation', 'The latest materialized observation for a metric — exactly what a metric-kind condition reads (status pass/fail, value, verdict, data-time). Check this before wiring an alert onto a metric.'),
('profile_schema', 'A fast overview of every (allowed) table: estimated row count + column count — to see which tables are populated WITHOUT running count(*) probes. Optionally scope to one schema. Row counts are planner estimates (pg_class.reltuples, ~0 if never analyzed); use describe_table for a full per-column profile of one table.'),
('propose_calliope_computer_action', 'Propose exactly one visible desktop action for a human to approve. Use this only for an active Guided Run shown in the current Calliope turn. Pass the exact session, workbench, and run UUIDs supplied by that turn. First inspect the attached current-desktop screenshot. `instruction` describes the single next action; `success` describes what should visibly change; `risk` is `read`, `write`, or `commit`; and `action` is one bounded control envelope. Use `{"kind":"click","x":512,"y":384,"target_text":"Exact visible label",` `"button":1}` for a click. `target_text` must exactly match the readable t'),
('propose_cube', 'Draft a candidate cube for a subject — a documented join over your tables. Returns a DRAFT only (name, sql, grain, description, source_tables, join_rationale, confidence + the FK edges it reasoned from); NOTHING is created. The draft is LOGGED to an optional proposal queue (returns its proposal_id). Call accept_proposal to publish a sound draft immediately, or use create_cube when you already have validated SQL; no separate UI approval is required. Pass seed_tables (schema.table list) to pin the join, or a schema to scope discovery.'),
('propose_metric', 'Draft a candidate metric for a subject — a small, governed aggregation, PREFERRING a cube as its source. Returns a DRAFT only (name, sql, grain, description, params, optional KPI check_sql, source, confidence) plus validated/sample from a dry-run; NOTHING is created. The draft is LOGGED to an optional proposal queue (returns its proposal_id). Call accept_proposal to publish it immediately, or use create_metric for already validated SQL; no separate UI approval is required. Pass seed_sources (cubes.x / schema.table list) or a schema.'),
('publish_answer', 'Publish a concise analytical takeaway as a large, full-width Stage answer block. Use when the user or a Playbook requests an answer callout (for example an Ask playbook), after synthesizing the evidence; not for ordinary conversation or interim progress. answer: one plain-text sentence, max 320 characters. caveat: optional short qualification, max 240 characters. Keep qualifications that change the conclusion in the answer itself. No Markdown/HTML styling; the Stage supplies typography and theme colors. evidence_refs: up to eight supporting Stage surface UUIDs from this chat (bare UUIDs or sur'),
('publish_chart', 'Publish a live SQL-backed Vega-Lite chart or composed exploration dashboard directly to this chat''s Stage. Works from Calliope and delegated specialists; no HTML or files needed. queries maps dataset names to validated SELECT SQL. Reference them in the native Vega-Lite spec with data: {name: "dataset_name"}, including in lookup.from.data. Do not embed rows or use data URLs. SQL runs under the viewer on open/refresh, with row_limit per dataset (default 5000, max 20000; aggregate larger datasets). Use layer, hconcat, vconcat, facet, repeat and params for bespoke views and linked selections. Nati'),
('publish_dashboard', 'Persist a dashboard so it lives + works OUTSIDE Cowork (a shareable URL + the lens app). Build `html` from the `dashboard_template` boilerplate (call that tool FIRST): it gets LIVE data through Cowork''s callMcpTool→run_sql bridge in-app, and the host''s injected rvbbitQuery when served — the SAME artifact works both places for signed-in viewers. New artifacts are private to their verified human owner until explicitly shared. Hand completed HTML to upload_artifact by allowlisted source_path once, then pass source_artifact_id here. Keep each data concern its OWN FLAT query in the composePayload p'),
('publish_map', 'Publish a declarative SQL-backed Mapbox map directly to the Stage. No HTML, JS or token required. queries maps dataset names to read-only SELECT SQL, executed under the viewer on open/refresh. sources maps source IDs to {dataset:''query_name'',longitude:''lon_column'',latitude:''lat_column''} OR {dataset:''query_name'',geometry:''geojson_geometry_column''} for Point/MultiPoint, LineString/ MultiLineString, Polygon/MultiPolygon. Coordinates must already exist; no automatic geocoding. Each source may include tooltip:[''name'',''value''] and point clustering options cluster:true, clusterRadius:50, clusterMaxZo'),
('read_calliope_page', 'Read a private living Page, its definition_version, standing brief, saved document, sources and history. Optional version reads a historical revision. Source access is rechecked; revoked evidence never exposes the old body.'),
('read_calliope_playbook', 'Load one identity-authorized Playbook contract before applying it. Owners may inspect any immutable version and see private provenance plus sharing controls. Other authorized people receive only the approved version; source/evidence references are included only when they can also view the source notebook. No caller identity argument is accepted.'),
('read_calliope_sketch', 'Read the current semantic contents and recent edit deltas of a Sketch. Call this before editing an existing Sketch, especially after the human has changed it. The result contains normalized element summaries and revisions, not raw editor JSON. It also returns the current compact DSL contract. `since_revision` can bound the edit history while the current semantic scene is always returned.'),
('read_chart', 'Read a Stage chart''s saved Vega-Lite spec and named SQL queries for inspection or revision, plus the latest browser render receipt/error and revision IDs. Does not execute queries. Use update_chart to repair the latest revision without stacking visible tiles. A missing render_receipt means no owner browser has reported a result yet.'),
('read_map', 'Read a Stage map''s SQL, sources, native Mapbox layers, viewport, latest revision ID and render_receipt/last_render_error. Does not execute queries. No receipt means no owner browser has reported yet. Use update_map on latest_surface_id to repair without stacking visible maps.'),
('read_page_refresh', 'Read the standing brief, current document and caller-visible cited Brain evidence for a requested living Page refresh. Use the run_id supplied by the refresh request. This is read-only and only works in that Page''s initiating turn. Finish with finish_page_refresh; conversational completion alone does not save the Page.'),
('record_acceleration_observation', 'Persist a bounded no-change or error conclusion for later learning.'),
('record_specialist_finding', 'Create or update one compact, non-secret specialist finding. Persistent Hermes memory is private working context. This ledger is the durable shared feedback surface for material observations, proposals, warnings, reviews, and actions from delegated or autonomous specialists. A stable dedupe_key updates an existing open/monitoring case rather than producing one finding per scheduled run. Evidence must never contain credentials, tokens, remote DSNs, or hidden reasoning.'),
('refine_proposal', 'Edit a PENDING proposal in place after seeing feedback — instead of submitting a duplicate. Only the fields you pass change. (Cube SQL is plain; metric SQL may use {param} tokens.) Pass category/subcategory to (re)file it under a folder before review.'),
('refresh_business_context', 'Observe one data domain and queue semantic refresh only when warranted. Normal calls are cheap and fingerprint-gated. Set force=true only when the physical schema is unchanged but its business interpretation should be reconsidered. Execution is durable and asynchronous.'),
('refresh_calliope_page', 'Prepare a cited living Page refresh in THIS conversation turn. Returns refresh_contract with run_id, standing brief, previous document and fresh caller-visible evidence. Synthesize here, then finish_page_refresh with [N] citations. Does not launch another agent. Retrying reuses this turn''s run; if already finished, report its outcome rather than executing again.'),
('render_pdf', 'Render HTML (or a stored live app by slug) to a PDF — the official- document leg of intake->extract->validate->document workflows (certs, permits, invoices). Rides the same bridge-injected playwright renderer as captures, so rvbbitQuery works inside the template: the PDF can pull LIVE rows at render time. Returns the served path (/pdfs/<name>.pdf).'),
('request_calliope_input', 'Ask a durable, non-secret question in the conversation''s decision panel. Required requests block new human messages until answered or cancelled. Set blocking=false only for optional questions that the human may skip. If this question resolves existing Work Inbox alerts, pass their exact IDs in work_item_ids (same originating chat only). Answering or cancelling will close those alerts too; answering no still counts as a decision. Use this when two or more concrete answers, a choice, or a short structured response would move the conversation forward more clearly than prose alone. The submitted a'),
('resolve_specialist_finding', 'Resolve or dismiss one specialist finding with a durable explanation.'),
('restart_hermes_gateway', 'Restart Hermes through the verified last-good configuration path. Admin-only mutation. This rehydrates canonical credential bindings and does not expose Docker, a shell, or the Hermes UI.'),
('restore_hermes_config', 'Queue a previous secret-free Hermes revision as a new verified revision. Admin-only mutation. The original revision remains immutable and the same automatic verification/rollback path is used.'),
('review_acceleration_trial', 'Retain, adjust, or retire one measured trial and record its outcome.'),
('run_alert_sweep', 'Run one reconciler sweep NOW for a tier (fast|normal|slow) instead of waiting for cron — evaluates conditions, diffs state, enqueues transitions. Returns the sweep summary. Pair with run_alert_worker to actually dispatch what it enqueues.'),
('run_alert_worker', 'Drain up to max_items from the action queue NOW (dispatch pending alert actions) instead of waiting for cron. Fire-and-forget; results land in alert_events. Returns the drain summary.'),
('run_calliope_procedure', 'Plan one supervised run of an approved Procedure discovered by capability_search. Pass the exact capability name returned in a cap_playbook result whose run_with.tool is run_calliope_procedure. The service pins the approved semantic version and validated execution strategy into a durable receipt; it never accepts credentials in inputs. At rehearsed/supervised trust the returned receipt must be opened and explicitly launched by the human.'),
('run_sql', 'Run governed SQL, binding the active private Sheet when referenced. The ordinary behavior is unchanged. The reserved, unqualified ``selected_sheet`` relation is recognized only when this request maps to an active browser-owned Calliope turn with a selected Sheet. Execution then delegates to the same owner-checked implementation as ``calliope_sheet_query``; this is not a second or weaker authorization path. Keep default_view=table for ordinary data; request chart only for a result deliberately shaped as a chart in response to explicit user intent. The default result remains 1,000 rows; an expli'),
('run_sql_multi', 'Batch governed SQL with the same selected-Sheet compatibility binding. Keep ordinary batches on the optimized implementation. If at least one statement uses the reserved transient relation and this request maps to an active private Sheet selection, execute each Sheet statement through the exact same authorization/query gate as ``calliope_sheet_query``. This covers older Hermes catalogs without teaching generic SQL about private rows or exposing request context in the public schema. Keep default_view=table unless every returned query is intentionally chart-shaped.'),
('run_workspace_sql', 'Build and repair data in calliope and application state in calliope_apps. Prefer this for normal local ETL/materialization work in an Admins Team session. Submit up to 50 SQL statements as one atomic batch: CREATE TABLE AS SELECT, INSERT/UPDATE/DELETE/MERGE, views/materialized views, indexes, ALTER TABLE, REFRESH MATERIALIZED VIEW, ANALYZE and SELECT verification. Qualify write targets as calliope.name or calliope_apps.name; qualify source tables as schema.name. Source reads use local exposed data tables/views; source mirrors stay intact. PostgreSQL built-ins, installed rvbbit operators (inclu'),
('save_workspace_job', 'Save/update a deterministic SQL ETL job in the calliope or calliope_apps workspace. Supply description: one plain-language sentence explaining purpose and tables maintained. Use for MCP/API SQL materializers, local transforms and rollups, including recurring workspace writes. Run and verify the SQL with run_workspace_sql first, then save that same idempotent batch here. No database source/DSN, DLT mirror, Workflow contract or additional approval is needed. The worker executes SQL directly, without waking Hermes or spending orchestration tokens. interval_seconds=0 saves a manual job; 43200 sche'),
('schedule_calliope_thread', 'Give the current conversation a standing heartbeat, or manage one. Use when the human asks to make this thread''s work recurring ("run this every morning", "make this a nightly job"). `session_id` must be the exact Calliope session UUID from the current turn''s internal routing context. action ''create'' (also reschedules) needs `schedule` as a five-field cron expression in the appliance''s local time, plus a `mission` (one paragraph: what each run should do) and/or an approved `playbook` capability name — approved playbooks are the preferred instruction carrier; a playbook without an approved vers'),
('scoreboard', 'The executive KPI matrix: every blessed metric laid out as category › subcategory (left axis) × time periods (top axis), each cell = the metric''s value that period, with its latest target verdict and a trend. Reads the materialized observation log (the governed history — no recompute). Filter by category; grain = day|week|month|quarter|year; periods = how many columns back. The ''how are we doing?'' view — render it as one opinionated matrix, not a flat list.'),
('search_business_context', 'Search the company''s interpreted business systems and metric meaning. Use this when the user asks what a domain means, which canonical metric represents an outcome, what contributes to it, or why it changed. Results distinguish promoted governance from review proposals and retain lineage.'),
('search_calliope_actions', 'Search outcome-oriented actions available to a Calliope user. Use the exact `session_id` from Calliope''s internal work-routing context; it resolves the owning human and current runtime state. Search in ordinary language such as "connect Linear", "retry the ERP mirror", "rotate the Linear key", "add tickets to company knowledge", or "monitor a metric". Results distinguish ready, connect/install, and blocked actions and include structured question fields. For any typed appliance installation, configuration, repair, mirror-control, Company Brain source, or credential action requested by an admini'),
('search_data', 'Search warehouse relations and catalog metadata by meaning. Find catalog metrics, cubes, tables, and columns with semantic search, usage weighting, and live table profiles. Business Context has its own dedicated tools. This does not search Company Brain documents, tickets, or meetings; use brain_facets + ask_brain there.'),
('search_hermes_docs', 'Search the exact, pre-enriched Hermes docs shipped with this appliance. Use this before changing Hermes messaging, gateway, profile, cron, plugin, or YAML settings. Results identify upstream pinned documentation separately from Calliope hosted-policy overlays. This corpus is not Company Brain and is never rebuilt on the customer appliance.'),
('search_tools', ''),
('semantic_enrichment_status', 'Inspect the non-blocking semantic compiler state for one immutable artifact version.'),
('set_alert_cadence', 'Move a rule to a sweep tier: ''fast'' (~1m), ''normal'' (~15m), or ''slow'' (~hourly).'),
('set_alert_enabled', 'Enable or disable a rule (control flag; survives re-definition). Disabled rules are skipped by the sweep. The non-destructive on/off — use this (or mute) to silence a noisy alert, not delete.'),
('set_alerts_enabled', 'The GLOBAL alerts kill-switch. on=false pauses ALL sweeps + actions at once (the circuit breaker); on=true resumes. Returns the new state. Pairs with the alerts_enabled flag in list_alerts.'),
('set_artifact_area', 'Manually assign a published artifact to an existing Area. Pass null to resume automatic classification.'),
('set_calliope_playbook_access', 'Replace an owned Playbook''s audience with exact Teams and people. Read the Playbook first and pass its access_revision. The owner is always implicit. Emails must be observed application principals; adding the protected Everyone Team requires confirm_everyone=true.'),
('set_category', 'Categorize a cube or metric (kind = ''cube'' | ''metric'') in the shared taxonomy — lightweight and mutable (no new version). Pass category=null to clear it. Use this to organize the catalog; read it back via list_cubes / list_metrics.'),
('start_acceleration_trial', 'Start a reversible acceleration trial without waiting for UI approval. Registration and policy activation are immediate; the five-slot tick fleet performs the baseline/freshness work asynchronously. A receipt freezes the pre-trial evidence and review date.'),
('start_live_app', 'Start a Python FastAPI live app locally under uvicorn. HTML apps are already hosted.'),
('stop_live_app', 'Stop a locally running Python live app process.'),
('sync_system_learning', 'Run the potentially expensive Brain reconciliation off the ASGI loop. FastMCP executes ordinary ``def`` tools inline on its request/event loop. System Learning can scan a large workload catalog and reconcile many Brain documents, so registering its synchronous implementation directly makes unrelated Calliope HTTP routes and MCP keepalives wait for the whole sync. ``asyncio.to_thread`` preserves request ContextVars while allowing the server to continue serving the UI and other MCP sessions.'),
('system_learning_status', ''),
('tanstack_chart_template', 'Get RVBBIT''s EXPERIMENTAL, opt-in TanStack Charts starter. It preserves the normal standalone HTML/JS dashboard model while replacing only selected visualization surfaces with native, responsive, keyed SVG chart definitions. The default Chart.js template is unchanged. Use this tool only when the user explicitly wants to try TanStack Charts or the semantic SVG primitive; publish with create_live_app and the returned manifest, then capture it.'),
('team_create', 'Create a flat Team. Only a current member of the Admins Team may do this. Members must first appear in team_people_search; arbitrary or inferred email addresses are rejected.'),
('team_get', 'Inspect one Team, its membership rule, revision, and recent receipts.'),
('team_list', 'List flat application Teams and their membership rules. Ordinary Teams and Admins contain explicit observed emails. Everyone is a protected dynamic rule matching any verified application subject and has no materialized member list.'),
('team_people_search', 'Search human emails observed through trusted Warehouse/Calliope requests. An observed person is a candidate for explicit Team membership; observation alone grants no access. Service actors and legacy attributed callers are excluded.'),
('team_update', 'Atomically change a Team after inspecting its current revision. Only Admins may mutate Teams. The protected Admins Team cannot be renamed or archived and must retain at least one member. Everyone is an immutable, dynamic authenticated-user wildcard with no explicit members. Repeated add/remove requests are idempotent; a stale expected_revision is rejected.'),
('unmute_alert', 'Clear a rule''s mute (resume its actions).'),
('update_calliope_page', 'Update a living Page''s enduring definition. Read it first and pass its definition_version as expected_version. Omitted fields are preserved. This changes the brief, not the saved document: use refresh_calliope_page afterward to obtain cited evidence, then finish_page_refresh to save revised content.'),
('update_calliope_sketch', 'Apply typed edits to the existing collaborative Sketch. Read the Sketch first and pass its exact current `expected_revision`; a concurrent human edit fails safely instead of being overwritten. Supported operations are add_text, add_shape, connect, set_text, move, resize, style, group, and delete. Shape and connector labels stay bound, and connectors reroute when an endpoint is moved or resized through this DSL. Preserve useful human-authored elements and use stable element ids. Do not author or replace raw Excalidraw scene JSON. Keep boxes and other shapes unfilled with style.background_color='),
('update_chart', 'Fix or revise an existing live Stage chart without adding another visible tile. First read_chart to inspect its saved queries/spec, latest_surface_id and render_receipt (query or Vega error, timestamp, status). Pass only fields you want to replace; spec and queries replace their entire objects, omitted fields are retained. Returns a new immutable surface_id in the same chart lineage; Stage shows its latest revision and preserves history. Obsolete revisions are rejected with the latest_surface_id. Works in active Calliope or delegated specialist turns. A publish is not proof of successful brows'),
('update_dashboard', 'Publish a new version of an existing dashboard (by slug). PREFERRED for revisions: edits=[{"find": exact current text, "replace": new text}] applied server-side to the current version — read it first with get_dashboard(slug, part=''html'') and copy `find` verbatim; each find must match exactly once (set "all": true to replace every occurrence); a stale find fails with EDIT_NOT_FOUND and nothing changes. Send full html (or an upload_artifact handle via source_artifact_id) only when restructuring the page. Omit manifest to retain the current semantic map; pass a manifest patch to revise its versio'),
('update_live_app', 'Publish a new version of a live app. Omitted source fields are preserved. PREFERRED for revisions of html apps: edits=[{"find": exact current text, "replace": new text}] applied server-side to the current version — read it first with get_live_app(slug, part=''html'') and copy `find` verbatim (whitespace included); each find must match exactly once (set "all": true to replace every occurrence); a stale find fails with EDIT_NOT_FOUND and nothing changes. Send full html (or an upload_artifact handle via source_artifact_id) only when restructuring the page — retyping a whole document is how sections'),
('update_map', 'Revise an existing Stage map, preserving its lineage and showing only its latest revision. Read it first with read_map. Omitted fields are retained; supplied sources/layers/queries replace those whole objects. Same declarative contract as publish_map; no JS. Requires an active turn in the map''s own chat. Stale revisions are rejected. Use render_receipt for targeted repairs.'),
('upload_artifact', 'Stage HTML and get an artifact_id handle for publish/update tools. Preferred for Calliope/Hermes: write the completed UTF-8 .html file beneath WAREHOUSE_CALLIOPE_EXPORT_ROOTS and pass source_path. Warehouse reads that allowlisted, read-only handoff directly; do not read the file back into the model, split it into chunks, or retransmit it as content. Inline content and append remain available for clients without a shared filesystem. Returns bytes + sha256. Artifacts expire after ~48h; they are staging, not storage.'),
('validate_hermes_config', 'Validate candidate Hermes YAML without changing or restarting anything. Admin-only. Validation uses both the exact pinned Hermes validator and the Calliope hosted invariants. `secret_bindings` maps environment names to canonical RVBBIT credential refs; the name may be referenced as `${env:NAME}` in YAML or consumed natively by a Hermes messaging adapter. Never pass a secret value.'),
('validate_sql', 'Plan, don''t execute — route_explain dry-run so Claude can self-correct cheaply.'),
('wiki_list_pages', 'List wiki pages (title, author, state, flag, verdict counts) — newest first. Filter by author key, adoption state, or flagged_only=true for the pages needing gardener attention.'),
('wiki_read_page', 'Read one wiki page in full (body, author, adoption state, Evidence-Lab verdict of linked claims, revision). A page in state auto_provisional is a working assumption — say so when leaning on it, and invite correction.'),
('wiki_set_page_state', 'Demote (''demoted''), retire (''retired''), or revive (''auto_provisional'') a wiki page. An explicit human ''this is wrong'' should demote; the gardener resolves flags by rewriting the page instead. Retired slugs stay retired until explicitly revived.'),
('wiki_write_page', 'Write (or revise) a shared wiki page of working knowledge: procedures, gotchas, data caveats, operational patterns — the narrative that structured claims can''t hold. Adopt-first: the page is served as a provisional working assumption immediately; no approval step. Pass claim_fingerprints (from business semantic assertions) to let the Evidence Lab flag the page if a linked claim is later contradicted. Rewriting a demoted/flagged page resolves the flag and revives it. Slug is kebab-case and stable — reuse it to revise, not to fork.'),
('withdraw_proposal', 'Retract a PENDING proposal you no longer want reviewed (status -> withdrawn).'),
('workspace_job_status', 'List saved SQL ETL jobs, schedules, pause/error state and recent runs. No bespoke catalog SQL needed. With job_name, include the original SQL action receipts and statement results. Shows SQL/hash/revision, next run, run times, commit/failure status and receipt IDs. These are deterministic workspace jobs; mirror_status remains the index for DLT database mirrors.')
